    nitidezDesc: { tr: "Bikübik filtrenin keskinleştirme gücü (0 = keskinleştirme yok).", en: "Sharpening strength of the bicubic filter (0 = none).", es: "Intensidad del realce del filtro bicúbico (0 = sin realce).", pt: "Intensidade da nitidez do filtro bicúbico (0 = nenhuma)." },
    fxaa: { tr: "Kenar yumuşatma (FXAA)", en: "Anti-aliasing (FXAA)", es: "Suavizado de bordes (FXAA)", pt: "Antisserrilhado (FXAA)" },
    anisotropico: { tr: "Anizotropik filtreleme", en: "Anisotropic filtering", es: "Filtrado anisotrópico", pt: "Filtragem anisotrópica" },
    dibujoHardware: { tr: "Donanım çizimi", en: "Hardware rendering", es: "Dibujo por hardware", pt: "Desenho por hardware" },
    dibujoHardwareDesc: { tr: "Kapalıyken yazılım rasterleştiricisi kullanılır: donanım OpenGL 4.3 desteklemiyorsa gerekir.", en: "Off uses the software rasterizer: it is needed when the hardware cannot give an OpenGL 4.3 context.", es: "Apagado usa el rasterizador por software: hace falta cuando el hardware no da un contexto OpenGL 4.3.", pt: "Desligado usa o rasterizador por software: é preciso quando o hardware não dá um contexto OpenGL 4.3." },
    anisotropicoDesc: { tr: "Eğik açıdan görülen dokular (zemin, duvarlar) daha keskin; GPU'ya biraz yük.", en: "Sharper textures seen at an angle (floors, walls); a little GPU cost.", es: "Texturas vistas en ángulo (suelos, paredes) más nítidas; algo de coste de GPU.", pt: "Texturas vistas em ângulo (chão, paredes) mais nítidas; um pouco de custo de GPU." },
    desactivado: { tr: "Kapalı", en: "Off", es: "Desactivado", pt: "Desligado" },
    fxaaDesc: { tr: "Tırtıklı kenarları büyütmeden önce yumuşatır.", en: "Smooths jagged edges before upscaling.", es: "Suaviza los bordes dentados antes de ampliar.", pt: "Suaviza as bordas serrilhadas antes da escala." },
    interna: { tr: "Çizim çözünürlüğü", en: "Render resolution", es: "Resolución de dibujo", pt: "Resolução de renderização" },
    internaDesc: { tr: "Oyunun en fazla kaç kat çözünürlükte çizileceği (varsayılan 2×). Otomatik, ekran yüksekliğine göre seçer (1080p: 2×, 1440p: 3×, 4K: 4×). Her adım ekran kartına karesi kadar yük bindirir: 2× dört kat, 4× on altı kat.", en: "The highest multiple of the native resolution the game is drawn at (default 2×). Auto picks it from your screen height (1080p: 2×, 1440p: 3×, 4K: 4×). Each step costs the square in GPU work: 2× is four times, 4× sixteen times.", es: "La mayor resolución, en múltiplos de la nativa, a la que se dibuja el juego (2× por defecto). Automático la elige según la altura de tu pantalla (1080p: 2×, 1440p: 3×, 4K: 4×). Cada paso cuesta su cuadrado en trabajo de GPU: 2× es cuatro veces, 4× dieciséis.", pt: "O maior múltiplo da resolução nativa em que o jogo é desenhado (padrão 2×). Auto escolhe pela altura da sua tela (1080p: 2×, 1440p: 3×, 4K: 4×). Cada passo custa o quadrado em trabalho da GPU: 2× é quatro vezes, 4× dezesseis vezes." },
    internaAuto: { tr: "Otomatik · %1", en: "Auto · %1", es: "Automático · %1", pt: "Auto · %1" },
    internaNativa: { tr: "yerel PS2", en: "native PS2", es: "PS2 nativa", pt: "nativa do PS2" },
    internaPesada: { tr: "güçlü ekran kartı gerekir", en: "needs a powerful GPU", es: "requiere una GPU potente", pt: "exige uma GPU potente" },
    internaExtrema: { tr: "deneysel, çok ağır", en: "experimental, very heavy", es: "experimental, muy pesada", pt: "experimental, muito pesado" },

    fpsLimite: { tr: "Kare hızı sınırı", en: "Frame rate limit", es: "Límite de FPS", pt: "Limite de quadros" },
    fpsLimiteDesc: { tr: "Pencerenin saniyede en fazla kaç kare çizeceği. Ekranınız: %1 Hz.", en: "Maximum frames per second the window draws. Your display: %1 Hz.", es: "Máximo de cuadros por segundo de la ventana. Tu pantalla: %1 Hz.", pt: "Máximo de quadros por segundo que a janela desenha. Seu monitor: %1 Hz." },
    sinLimite: { tr: "Sınırsız", en: "Unlimited", es: "Sin límite", pt: "Sem limite" },
    vsync: { tr: "Dikey eşitleme (VSync)", en: "Vertical sync (VSync)", es: "Sincronía vertical (VSync)", pt: "Sincronização vertical (VSync)" },
    vsyncDesc: { tr: "Görüntü yırtılmasını önler; ekranın yenileme hızına kilitler.", en: "Prevents tearing; locks to the display refresh rate.", es: "Evita el tearing; se ajusta al refresco de la pantalla.", pt: "Evita o tearing; trava na taxa de atualização do monitor." },
    mostrarFps: { tr: "FPS göstergesi", en: "FPS counter", es: "Contador de FPS", pt: "Contador de FPS" },
    mostrarFpsDesc: { tr: "Köşede oyunun ve pencerenin kare hızını gösterir.", en: "Shows the game and window frame rates in a corner.", es: "Muestra en una esquina los FPS del juego y de la ventana.", pt: "Mostra as taxas de quadros do jogo e da janela num canto." },
    notaFpsTitulo: { tr: "Kare hızı hakkında", en: "About frame rate", es: "Sobre los FPS", pt: "Sobre a taxa de quadros" },
    notaFps: { tr: "Oyunun kendisi en fazla 60 kare üretir: mantığı PS2'nin 60 Hz VBlank'ine bağlıdır. Pencereyi 120 Hz ve üstünde çizmek yeni kareyi daha erken gösterir ve gecikmeyi azaltır. En ağır sahneler işlemciye bağlıdır.", en: "The game itself produces at most 60 frames: its logic is tied to the PS2's 60 Hz VBlank. Drawing the window at 120 Hz or more shows each new frame sooner and lowers latency. The heaviest scenes are CPU-bound.", es: "El juego produce como mucho 60 cuadros: su lógica va ligada al VBlank de 60 Hz de la PS2. Dibujar la ventana a 120 Hz o más muestra antes cada cuadro y reduce la latencia. Las escenas más pesadas dependen de la CPU.", pt: "O jogo em si produz no máximo 60 quadros: sua lógica está presa ao VBlank de 60 Hz do PS2. Desenhar a janela a 120 Hz ou mais mostra cada quadro novo mais cedo e reduz a latência. As cenas mais pesadas dependem da CPU." },

    elf: { tr: "Oyun dosyası (SCUS_973.99)", en: "Game executable (SCUS_973.99)", es: "Ejecutable del juego (SCUS_973.99)", pt: "Executável do jogo (SCUS_973.99)" },
    elfDesc: { tr: "Diskteki ana PS2 programı. Oyun verileri aynı klasörde aranır.", en: "The main PS2 program from the disc. Game data is looked up in the same folder.", es: "El programa principal de PS2 del disco. Los datos se buscan en su misma carpeta.", pt: "O programa principal do PS2, do disco. Os dados do jogo são procurados na mesma pasta." },
    elfOk: { tr: "Doğrulandı: God of War (NTSC-U, SCUS-97399)", en: "Verified: God of War (NTSC-U, SCUS-97399)", es: "Verificado: God of War (NTSC-U, SCUS-97399)", pt: "Verificado: God of War (NTSC-U, SCUS-97399)" },
    elfMal: { tr: "Bu dosya God of War NTSC-U değil (CRC %1)", en: "This file is not God of War NTSC-U (CRC %1)", es: "Este archivo no es God of War NTSC-U (CRC %1)", pt: "Este arquivo não é o God of War NTSC-U (CRC %1)" },
