    isoFalta: { tr: "Disk görüntüsü veya çıkarılmış oyun dosyaları bulunamadı", en: "No disc image or extracted game files found", es: "No hay imagen de disco ni archivos extraídos", pt: "Nenhuma imagem de disco ou arquivo extraído do jogo encontrado" },
