    perfilDesc: { tr: "Aşağıdaki ayarları tek seferde seçer. Oyunda F1 ile canlı ayarlanabilir.", en: "Sets the options below in one go. F1 in game adjusts them live.", es: "Ajusta las opciones de abajo de una vez. F1 en el juego las cambia en vivo.", pt: "Ajusta as opções abaixo de uma vez. F1 no jogo muda tudo ao vivo." },
    perfilBajo: { tr: "Düşük donanım", en: "Low-spec", es: "Bajo rendimiento", pt: "Baixo desempenho" },
