    grupoHerramientas: { tr: "ÖLÇEKLEME VE ARAÇLAR", en: "UPSCALING AND TOOLS", es: "ESCALADO Y HERRAMIENTAS", pt: "UPSCALING E FERRAMENTAS" },
    grupoEfectos: { tr: "EFFEKT ANAHTARLARI (YENİDEN BAŞLATMA)", en: "EFFECT SWITCHES (RESTART)", es: "INTERRUPTORES DE EFECTOS (REINICIAR)", pt: "CHAVES DE EFEITOS (REINICIAR)" },
    fxSinNiebla: { tr: "Sis kapalı", en: "Fog off", es: "Niebla desactivada", pt: "Névoa desligada" },
    fxSinNieblaDesc: { tr: "Oyunun uzak geometriye uyguladığı sis karışımını kaldırır. Yalnızca görüntü; sisin gizlediği uzak geometri görünebilir.", en: "Removes the fog blend applied to distant geometry. Visual only; distant geometry the fog hid may become visible.", es: "Quita la mezcla de niebla aplicada a la geometría lejana. Solo visual; puede aparecer geometría lejana que la niebla ocultaba.", pt: "Remove a mistura de névoa aplicada à geometria distante. Apenas visual; geometria distante que a névoa escondia pode aparecer." },
    fxSinSombras: { tr: "Karakter gölgeleri kapalı", en: "Character shadows off", es: "Sombras de personajes desactivadas", pt: "Sombras de personagens desligadas" },
    fxSinSombrasDesc: { tr: "Gölge hacmi sayım geçişlerini atlar. Karakter ve nesne gölgeleri kaybolur; yansımalar ve ışık kalır. Oyunu etkilemez.", en: "Skips the shadow-volume count passes. Character and object shadows disappear; reflections and lighting stay. It does not affect gameplay.", es: "Omite las pasadas de conteo del volumen de sombra. Desaparecen las sombras de personajes y objetos; las reflexiones y la iluminación se mantienen. No afecta al juego.", pt: "Pula as passagens de contagem do volume de sombra. Sombras de personagens e objetos somem; reflexos e iluminação permanecem. Não afeta a jogabilidade." },
    fxSinAditivos: { tr: "Toplamalı parlaklık kapalı", en: "Additive glow off", es: "Brillo aditivo desactivado", pt: "Brilho aditivo desligado" },
    fxSinAditivosDesc: { tr: "3B toplamalı çizimleri atlar (ateş, parlaklık, büyü kıvılcımları). Gölgeler ayrı anahtardadır. Bazı oyun ipuçları daha az okunur olabilir.", en: "Skips 3D additive draws (fire, glow, magic sparks). Shadows have their own switch. Some gameplay cues may be less readable.", es: "Omite los dibujos aditivos 3D (fuego, brillo, chispas mágicas). Las sombras tienen su propio interruptor. Algunas pistas de juego pueden leerse peor.", pt: "Pula os desenhos aditivos 3D (fogo, brilho, faíscas mágicas). As sombras têm seu próprio interruptor. Algumas dicas de jogo podem ficar menos legíveis." },
    fxSinFiltrado: { tr: "Doku filtrelemesini kapat (en yakın)", en: "Disable texture filtering (nearest)", es: "Desactivar filtrado de texturas (vecino)", pt: "Desativar filtragem de texturas (vizinho)" },
    fxSinFiltradoDesc: { tr: "Dokuları en yakın komşuyla örnekler: daha keskin, daha pikselli ve titrek. GPU bant genişliğini azaltır.", en: "Samples textures with nearest neighbour: sharper, more pixelated and shimmering. Uses less GPU bandwidth.", es: "Muestrea texturas con el vecino más cercano: más nítido, más pixelado y con parpadeo. Usa menos ancho de banda de GPU.", pt: "Amostra texturas com o vizinho mais próximo: mais nítido, mais pixelado e tremeluzente. Usa menos banda da GPU." },
    fxAviso: { tr: "Yeniden başlatmada uygulanır", en: "Applies on restart", es: "Se aplica al reiniciar", pt: "Aplica ao reiniciar" },
    fxAvisoDesc: { tr: "Bu anahtarlar oyun açılırken okunur: değiştirdikten sonra oyunu kapatıp yeniden açın. Hepsi kapalıyken görüntü özgün hâlindedir.", en: "These switches are read when the game starts: close and reopen the game after changing them. All off keeps the original picture.", es: "Estos interruptores se leen al iniciar el juego: ciérralo y vuelve a abrirlo tras cambiarlos. Todos apagados mantiene la imagen original.", pt: "Estes interruptores são lidos ao iniciar o jogo: feche e reabra o jogo após mudá-los. Tudo desligado mantém a imagem original." },
    upNativo: { tr: "Yerleşik ölçekleme", en: "Built-in upscaling", es: "Escalado integrado", pt: "Upscaling nativo" },
    upNativoDesc: { tr: "Oyun, iç çözünürlükte gerçekten daha fazla piksel çizer (2×, 3×…); keskin filtre ve FXAA sonra ekrana uydurur. GPU ağırsa iç çözünürlüğü düşürmek FPS kazandırır; CPU sınırlı sahnelerde değişmez.", en: "The game really draws more pixels at the internal resolution (2×, 3×…); the sharp filter and FXAA then fit it to your screen. Lowering the internal resolution gains FPS when the GPU is the limit; it does not help CPU-bound scenes.", es: "El juego dibuja de verdad más píxeles a la resolución interna (2×, 3×…); el filtro nítido y el FXAA la ajustan a tu pantalla. Bajar la resolución interna da FPS si la GPU es el límite; no ayuda en escenas limitadas por la CPU.", pt: "O jogo desenha de verdade mais pixels na resolução interna (2×, 3×…); o filtro nítido e o FXAA ajustam à sua tela. Baixar a resolução interna dá FPS quando a GPU é o limite; não ajuda em cenas limitadas pela CPU." },
    upDlss: { tr: "DLSS / FSR 2–3 / XeSS", en: "DLSS / FSR 2–3 / XeSS", es: "DLSS / FSR 2–3 / XeSS", pt: "DLSS / FSR 2–3 / XeSS" },
    upDlssDesc: { tr: "Kullanılamaz: hareket vektörleri ve DirectX 12/Vulkan ister; PS2 grafik birimi (OpenGL) bunları vermez. Yerine yerleşik ölçeklemeyi kullanın.", en: "Not available: they need motion vectors and DirectX 12/Vulkan; the PS2 graphics unit (OpenGL here) provides neither. Use the built-in upscaling instead.", es: "No disponible: necesitan vectores de movimiento y DirectX 12/Vulkan; la unidad gráfica del PS2 (aquí OpenGL) no los da. Usa el escalado integrado.", pt: "Indisponível: exigem vetores de movimento e DirectX 12/Vulkan; a unidade gráfica do PS2 (aqui em OpenGL) não fornece isso. Use o upscaling nativo." },
    upNoDisponible: { tr: "Yok", en: "Not available", es: "No disponible", pt: "Indisponível" },
    upExternas: { tr: "Harici araçlara izin ver", en: "Allow external tools", es: "Permitir herramientas externas", pt: "Permitir ferramentas externas" },
    upExternasDesc: { tr: "Lossless Scaling (ölçekleme / kare üretimi), ReShade (OpenGL) ve OBS kenarsız pencereyi görür: açıkken görüntü modu kenarsız olur. Bu araçlar resmi olarak test edilmedi; gecikme ekleyebilirler.", en: "Lossless Scaling (scaling / frame generation), ReShade (OpenGL) and OBS see a borderless window: on, the display mode becomes borderless. These tools are not officially tested and may add latency.", es: "Lossless Scaling (escalado / generación de fotogramas), ReShade (OpenGL) y OBS ven una ventana sin bordes: activado, el modo de pantalla pasa a sin bordes. No están probadas oficialmente y pueden añadir retraso.", pt: "Lossless Scaling (escala / geração de quadros), ReShade (OpenGL) e OBS enxergam a janela sem bordas: ligado, o modo de exibição vira sem bordas. Essas ferramentas não são testadas oficialmente e podem adicionar atraso." },
